(7559977, 1211432, 50695, '<td valign="top">great texture with the verticals on the window contrasting with the diagonals of the fan motion. that is great motion blur by the way. I''ve only ever seen blur like that on butterflies.</td>', 'great texture with the verticals on the window contrasting with the diagonals of the fan motion. that is great motion blur by the way. I''ve only ever seen blur like that on butterflies.', '2018-02-18 20:21:04.000000', NULL, 1),
(7559978, 1211719, 50695, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1077279" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/50695/120/Copyrighted_Image_Reuse_Prohibited_1077279.jpg"/></a> <br/> <br/>What is art? Art is two impossibly different things facing each other across an eternity and becoming one.<br/><br/><i>Message edited by author 2018-02-19 12:41:05.</i></td>', '  What is art? Art is two impossibly different things facing each other across an eternity and becoming one.', '2018-02-18 20:21:56.000000', '2018-02-19 12:41:05.000000', 1),
